package com.nthexperience.desktop;

import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Real Android view layout/rotation with deterministic portrait and side-camera inset fixtures. */
public final class EightInsetsSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;ViewGroup shell;FrameLayout layer;DesktopIconGrid grid;EightAppSwitcher switcher;EightCharms charms;android.graphics.Insets bars;Rect camera;int left,top,right;WindowInsets original;
    public void onCreate(Bundle args){EightTestSetup.afterInitialization(getTargetContext());super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("show_status_bar",false).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();grid=EightSmoke.find(root,DesktopIconGrid.class);shell=(ViewGroup)grid.getParent().getParent().getParent();switcher=EightSmoke.find(root,EightAppSwitcher.class);charms=EightSmoke.find(root,EightCharms.class);layer=(FrameLayout)charms.getParent();original=root.getRootWindowInsets();check(original!=null,"Real window insets delivered");String saved=store.prefs.getString("desktop_positions_landscape","");
        scenario("portrait-hidden",ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,0,48,0,false);
        scenario("portrait-status",ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,0,48,0,true);
        scenario("landscape-camera-left",ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,66,0,0,false);
        scenario("landscape-camera-right",ActivityInfo.SCREEN_ORIENTATION_REVERSE_LANDSCAPE,0,0,66,false);
        check(saved.equals(store.prefs.getString("desktop_positions_landscape","")),"Camera/rotation layout does not rewrite saved icon positions");
        ui(()->{charms.dismiss();switcher.dismiss();shell.dispatchApplyWindowInsets(root.getRootWindowInsets());store.prefs.edit().putBoolean("show_status_bar",false).commit();home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);});
        result.putString("stream","PASS: native portrait panels reach the top with hidden/shown status bar and camera-safe controls; actual landscape and reverse-landscape rotations with deterministic left/right camera insets; bottom arrows meet both navigation-safe screen edges and remain above taskbar; straight camera-safe desktop icon columns; Start/settings/immersive contents retain camera clearance; saved icon positions unchanged\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){try{shot("eight-insets-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
    void scenario(String name,int orientation,int l,int t,int r,boolean status)throws Exception{
        ui(()->{charms.dismiss();switcher.dismiss();home.open("@desktop");store.prefs.edit().putBoolean("show_status_bar",status).commit();home.setRequestedOrientation(orientation);});SystemClock.sleep(500);waitForIdleSync();left=dp(l);top=dp(t);right=dp(r);inject(status);
        ui(()->{Rect viewport=bounds(layer),first=bounds(grid.getChildAt(0));check(grid.getChildCount()>=3,"Desktop shortcuts exist");check(layer.getPaddingLeft()==bars.left&&layer.getPaddingRight()==bars.right,"Overlay retains navigation, not camera side margins");check(first.left>=Math.max(bars.left,left),"First icon column clears camera");for(int i=0;i<grid.getChildCount();i++)check(!Rect.intersects(bounds(grid.getChildAt(i)),camera),"Desktop tile avoids actual camera bounds");if(l>0){View a=grid.getChildAt(0),b=grid.getChildAt(1),c=grid.getChildAt(2);check(a.getLeft()==b.getLeft()&&b.getLeft()==c.getLeft()&&a.getTop()<b.getTop()&&b.getTop()<c.getTop(),"Left camera no longer scatters the first column");}View a=EightSmoke.description(root,"Open app switcher"),b=EightSmoke.description(root,"Open Charms"),task=EightSmoke.description(root,"Desktop taskbar");Rect ab=bounds(a),bb=bounds(b),tb=bounds(task);check(ab.left==viewport.left+bars.left&&bb.right==viewport.right-bars.right,"Bottom arrows meet both screen edges");check(ab.bottom<=tb.top&&bb.bottom<=tb.top,"Bottom arrows stay above taskbar");check(!Rect.intersects(ab,camera)&&!Rect.intersects(bb,camera),"Edge arrows avoid camera and nav controls");});shot("eight-insets-"+name+"-desktop");
        ui(switcher::show);inject(status);ui(()->{check(bounds(switcher.scroll).top==bounds(layer).top,"Switcher background reaches top");check(bounds(switcher.list.getChildAt(0)).top>=Math.max(top,bars.top),"Switcher heading clears camera/status");check(bounds(switcher.list.getChildAt(1)).left>=Math.max(left,bars.left),"Switcher card clears side camera");});shot("eight-insets-"+name+"-switcher");
        ui(()->{switcher.dismiss();charms.show("charms");});inject(status);ui(()->{check(bounds(charms.scroller).top==bounds(layer).top,"Charms background reaches top");for(String label:new String[]{"Search","Share","Start","Devices","Settings"}){View charm=EightSmoke.description(charms,label+" charm");check(charm!=null&&charm.isShown()&&!Rect.intersects(bounds(charm),camera),"Charm control avoids camera "+label);}check(bounds(charms.scroller).right==bounds(layer).right-bars.right,"Right panel reaches navigation-safe edge");});shot("eight-insets-"+name+"-charms");
        for(String id:new String[]{"@start","@settings","@calendar"}){ui(()->{charms.dismiss();if(id.equals("@calendar"))home.openEightTile(id);else home.open(id);});inject(status);ui(()->{View page=id.equals("@start")?EightSmoke.find(root,EightStartScreen.class):id.equals("@settings")?EightSmoke.find(root,EightPCSettings.class):EightSmoke.find(root,EightImmersive.class);Rect p=bounds(page);check(p.top>=Math.max(top,bars.top)&&p.left>=Math.max(left,bars.left)&&p.right<=root.getWidth()-Math.max(right,bars.right),"Page contents retain camera-safe bounds "+id);});}
    }
    void inject(boolean status)throws Exception{ui(()->{WindowInsets base=root.getRootWindowInsets();android.graphics.Insets nav=base.getInsets(WindowInsets.Type.navigationBars());bars=android.graphics.Insets.of(nav.left,Math.max(nav.top,status?dp(24):0),nav.right,nav.bottom);int w=root.getWidth(),h=root.getHeight();camera=left>0?new Rect(0,h/2-dp(24),left,h/2+dp(24)):right>0?new Rect(w-right,h/2-dp(24),w,h/2+dp(24)):new Rect(w/2-dp(24),0,w/2+dp(24),top);DisplayCutout cutout=new DisplayCutout(new Rect(left,top,right,0),Collections.singletonList(camera));WindowInsets fixture=new WindowInsets.Builder(base).setInsets(WindowInsets.Type.systemBars(),bars).setInsets(WindowInsets.Type.ime(),android.graphics.Insets.NONE).setDisplayCutout(cutout).setInsets(WindowInsets.Type.displayCutout(),android.graphics.Insets.of(left,top,right,0)).build();shell.dispatchApplyWindowInsets(fixture);});SystemClock.sleep(150);waitForIdleSync();}
    int dp(int value){return Aero.dp(getTargetContext(),value);}Rect bounds(View view){int[] p=new int[2];view.getLocationOnScreen(p);return new Rect(p[0],p[1],p[0]+view.getWidth(),p[1]+view.getHeight());}
    void ui(Runnable action)throws Exception{FutureTask<Void> t=new FutureTask<>(action,null);home.runOnUiThread(t);t.get(20,TimeUnit.SECONDS);waitForIdleSync();}
    void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
    void shot(String name)throws Exception{Bitmap b=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);ui(()->root.draw(new Canvas(b)));try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
